function readSetting(name) {
  try {
    if (typeof $env !== "undefined" && $env && $env[name]) return String($env[name]);
  } catch (error) {
    // n8n Cloud blocks $env inside nodes; fall through to Global Variables.
  }
  try {
    if (typeof $vars !== "undefined" && $vars && $vars[name]) return String($vars[name]);
  } catch (error) {
    // Self-hosted Community has no Global Variables; fall through.
  }
  return "";
}

function requireSetting(name) {
  const value = readSetting(name);
  if (!value) {
    throw new Error(
      name + " is not configured. Set it as an n8n environment variable ($env) or a Global Variable ($vars).",
    );
  }
  return value;
}

function sign(timestamp, body) {
  const secret = requireSetting("N8N_HMAC_SECRET");
  return require("crypto")
    .createHmac("sha256", secret)
    .update(timestamp + "." + body, "utf8")
    .digest("hex");
}

function convexBaseUrl() {
  return requireSetting("LENDLOOP_CONVEX_SITE_URL").replace(/\/+$/, "");
}

function escapeHtml(value) {
  return String(value === null || value === undefined ? "" : value).replace(
    /[&<>"']/g,
    (character) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character],
  );
}

const timestamp = String(Date.now());
const signature = sign(timestamp, "");

return [
  {
    json: {
      url: convexBaseUrl() + "/n8n/overdue",
      headers: {
        "x-lendloop-timestamp": timestamp,
        "x-lendloop-signature": signature,
      },
    },
  },
];

