  );
}

const response = $input.first().json || {};
const loans = Array.isArray(response.loans) ? response.loans : [];

// Workflow static data is the in-n8n half of idempotency: the Convex ledger
// rejects a repeated key, and this stops the reminder being emailed twice in
// the first place.
const store = $getWorkflowStaticData("global");
store.sent = store.sent && typeof store.sent === "object" ? store.sent : {};
const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
for (const key of Object.keys(store.sent)) {
  if (typeof store.sent[key] === "number" && store.sent[key] < cutoff) {
    delete store.sent[key];
  }
}

const from = readSetting("LENDLOOP_FROM_EMAIL") || "LendLoop <notifications@example.com>";
const reminders = [];

for (const loan of loans) {
  const idempotencyKey = "overdue-reminder:" + loan.loanId + ":" + loan.dueDate;
  if (store.sent[idempotencyKey]) continue;

  const borrowerName = loan.borrowerName || "there";
  const toolName = loan.toolName || "a tool";
  const subject = "LendLoop: " + toolName + " is " + loan.daysOverdue + " day(s) overdue";
  const text = [
    "Hi " + borrowerName + ",",
    "",
    toolName + " was due back on " + loan.dueDate + " and is now " + loan.daysOverdue + " day(s) overdue.",
    "Please return it, or message " + (loan.ownerName || "the owner") + " to arrange an extension.",
    "",
    "You are receiving this because you have an open loan in LendLoop.",
  ].join("\n");

  const html = [
    "<p>Hi " + escapeHtml(borrowerName) + ",</p>",
    "<p><strong>" + escapeHtml(toolName) + "</strong> was due back on " + escapeHtml(loan.dueDate) + " and is now <strong>" + escapeHtml(loan.daysOverdue) + " day(s) overdue</strong>.</p>",
    "<p>Please return it, or message " + escapeHtml(loan.ownerName || "the owner") + " to arrange an extension.</p>",
  ].join("");

  reminders.push({
    json: {
      loanId: loan.loanId,
      dueDate: loan.dueDate,
      daysOverdue: loan.daysOverdue,
      idempotencyKey,
      from,
      to: loan.borrowerEmail,
      subject,
      text,
      html,
    },
  });
}

// No pending reminders means no items, so the rest of the workflow is skipped
// and the execution still finishes green.
return reminders;

