const results = $input.all();
const prepared = $('Prepare reminders').all();
const base = convexBaseUrl();
const now = Date.now();

return results.map((result, index) => {
  const reminder = (prepared[index] || { json: {} }).json;
  const body = JSON.stringify({
    idempotencyKey: reminder.idempotencyKey,
    loanId: reminder.loanId,
    kind: "overdue",
    status: "sent",
    sentAt: now,
  });
  const timestamp = String(now);
  return {
    json: {
      idempotencyKey: reminder.idempotencyKey,
      url: base + "/n8n/reminder-result",
      body,
      headers: {
        "x-lendloop-timestamp": timestamp,
        "x-lendloop-signature": sign(timestamp, body),
      },
      emailId: (result.json && result.json.id) || null,
    },
  };
});

