}

const responses = $input.all().map((item) => item.json || {});
const duplicates = responses.filter((response) => response.duplicate === true).length;

return [
  {
    json: {
      attempted: written.length,
      duplicates,
      remembered: Object.keys(store.sent).length,
    },
  },
];
